// src/components/FilmCard.jsx
import React from 'react';

const FilmCard = ({ film }) => {
  return (
    <div className="film-card">
      {/* Припускаючи, що ви маєте стилі для .film-card-thumb та .film-card-img */}
      <div className="film-card-thumb">
        {/* Можливо, тут є зображення, але поки що це заглушка */}
        <p>Image placeholder for: {film.image}</p>
      </div>
      
      {/* Використовуємо .film-card-h4 зі свого CSS */}
      <h4 className="film-card-h4">{film.name}</h4>
      <p>Time: {film.time} min</p>
      <p>IMDb: {film.IMDb_rating}</p>
      <p>Reviews: {film.number_reviews}</p>
    </div>
  );
};

export default FilmCard;
